/* @lc app=leetcode id=3742 lang=kotlin */ class Solution { fun maxPathScore(grid: Array<IntArray>, k: Int): Int = grid[0].size.let { n -> grid.indices.fold(Array(n) { IntArray(k + 1) { -1 } }) { prev, i -> Array(n) { IntArray(k + 1) { -1 } }.also { cur -> (0 until n).forEach { j -> grid[i][j].let { g -> (if (g == 0) 0 else 1).let { cost -> (cost..k).forEach { c -> (if (i == 0 && j == 0) (if (c == 0) 0 else -1) else maxOf(if (i > 0) prev[j][c - cost] else -1, if (j > 0) cur[j - 1][c - cost] else -1)).let { b -> cur[j][c] = if (b >= 0) b + g else -1 } } } } } } }.last().max() } }